test("canonical Decision Explanation carries a Candidate Generation Proof", async () => {
  for (const event of events) {
    const decoded = await decodeReviewSessionEventEnvelope(event)
    if (
      decoded.event.kind !== "completed" ||
      decoded.event.result.kind !== "reviewMomentExplanationRead"
    ) {
      continue
    }
    const path = decoded.event.result.explanation.selectedPaths[0]
    if (!path) {
      throw new Error("canonical Decision Explanation must select a path")
    }
    const proof = path.candidateGenerationProof
    if (!proof) {
      throw new Error(
        "canonical Decision Explanation must prove candidate generation",
      )
    }
    expect(proof.suggestedCandidateRef).toBe(path.candidateRef)
    if (proof.positionGoal.kind !== "gainMaterial") {
      throw new Error("canonical Position Goal must gain material")
    }
    expect(proof.positionGoal.targets).not.toHaveLength(0)
    return
  }
  throw new Error("canonical events must include a Decision Explanation read")
})

