test("decodes an addressable snapshot and rejects unsteppable moment sets", () => {
  expect(decodeGameReviewSnapshot(gameReviewSnapshot)).toEqual(
    gameReviewSnapshot,
  )
  // Stepping to the next Critical Moment is an index step, so a gap makes
  // "next" mean some other moment.
  expect(() =>
    decodeGameReviewSnapshot({
      ...gameReviewSnapshot,
      moments: [{ ...gameReviewSnapshot.moments[0], index: 1 }],
    }),
  ).toThrow(/index/)
  expect(() =>
    decodeGameReviewSnapshot({
      ...gameReviewSnapshot,
      moments: [
        gameReviewSnapshot.moments[0],
        { ...gameReviewSnapshot.moments[0], index: 1 },
      ],
    }),
  ).toThrow(/moments/)
  expect(() =>
    decodeGameReviewSnapshot({
      ...gameReviewSnapshot,
      maxPly: 0,
    }),
  ).toThrow(/maxPly/)
  expect(() =>
    decodeGameReviewSnapshot({
      ...gameReviewSnapshot,
      moments: [
        {
          ...gameReviewSnapshot.moments[0],
          selection: {
            criticalMomentId: "review-moment:other:1",
            kind: "pipelineCriticalMoment",
          },
        },
      ],
    }),
  ).toThrow(/selection/)
  // A moment offers at most one continuation of each kind, so a repeated kind
  // would give the selector two buttons addressing one line.
  expect(() =>
    decodeGameReviewSnapshot({
      ...gameReviewSnapshot,
      moments: [
        {
          ...gameReviewSnapshot.moments[0],
          sequenceKinds: ["engineBest", "engineBest"],
        },
      ],
    }),
  ).toThrow(/sequenceKinds/)
})

