test("generated rate-limit outcome stays rateLimited plus retryAfter", async () => {
  const limited = events.find(
    (event) =>
      event.event.kind === "unavailable" &&
      event.event.reason.kind === "rateLimited",
  )
  if (!limited) {
    throw new Error("canonical events must include a rate-limited outcome")
  }
  const decoded = await decodeReviewSessionEventEnvelope(limited)
  expect(decoded.event).toMatchObject({
    kind: "unavailable",
    reason: { kind: "rateLimited", retryAfterSeconds: 60 },
    retry: { kind: "retryAfter", seconds: 60 },
  })
})
